class _deliveries:
    """Operations of deliveries."""

    def __init__(self, client: Client) -> None:
        self._client = client

    def list_deliveries(
        self,
        *,
        state: Optional[Literal["all", "failed", "pending"]] = None,
        form_id: Optional[str] = None,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "DeliveryPage":
        """The form delivery ledger

        comms_form_deliveries: the receipt and the owner notification of every submission, statuses only (kit.form-notification.v1). No address and no submitted value is stored there.

        GET /api/deliveries
        """
        return self._client.request("listDeliveries", {"state": state, "form_id": form_id, "limit": limit, "cursor": cursor}, OMITTED, headers, timeout)

    def get_delivery(
        self,
        *,
        reference: "Reference",
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "KitFormNotificationV1":
        """One delivery record

        kit.form-notification.v1.

        GET /api/deliveries/{reference}
        """
        return self._client.request("getDelivery", {"reference": reference}, OMITTED, headers, timeout)

    def retry_delivery(
        self,
        *,
        reference: "Reference",
        idempotency_key: str,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "RetryResult":
        """Retry a failed delivery through the comms engine

        Re-submits the stored submission under the SAME reference to the comms engine's POST /v1/comms/submit, which re-drives only the deliveries that did not go and picks the templates and the recipients itself: the admin chooses neither. Needs the stored lead of that reference. Idempotency-Key required. Audited before and after the call.

        POST /api/deliveries/{reference}/retry
        """
        return self._client.request("retryDelivery", {"reference": reference, "Idempotency-Key": idempotency_key}, OMITTED, headers, timeout)

    def list_owner_alert_failures(
        self,
        *,
        window_hours: Optional[int] = None,
        limit: Optional[int] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "OwnerAlerts":
        """Owner-alert failures

        Form submissions whose owner notification failed or is still pending past the window, and failed dispatches of the operator templates. The deliveries summary is the one the monitor reads.

        GET /api/alerts
        """
        return self._client.request("listOwnerAlertFailures", {"window_hours": window_hours, "limit": limit}, OMITTED, headers, timeout)


