class _leads:
    """Operations of leads."""

    def __init__(self, client: Client) -> None:
        self._client = client

    def list_leads(
        self,
        *,
        status: Optional["LeadStatus"] = None,
        form: Optional[str] = None,
        q: Optional[str] = None,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "LeadPage":
        """List and filter leads

        Newest first. A page can hold fewer rows than `limit` while next_cursor is set: the status filter is applied to a bounded window of the leads table (docs/ADMIN.md).

        GET /api/leads
        """
        return self._client.request("listLeads", {"status": status, "form": form, "q": q, "limit": limit, "cursor": cursor}, OMITTED, headers, timeout)

    def export_leads(
        self,
        *,
        status: Optional["LeadStatus"] = None,
        form: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> str:
        """Export leads as CSV

        At most 5000 rows, newest first, the same filters as listLeads. Cells that start with = + - @ are neutralised (CSV formula injection). Every export is audited.

        GET /api/leads/export
        """
        return self._client.request("exportLeads", {"status": status, "form": form}, OMITTED, headers, timeout)

    def get_lead(
        self,
        *,
        id: "LeadId",
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "Lead":
        """One lead

        The stored lead with its status and note. The email address is shown here and in the export only.

        GET /api/leads/{id}
        """
        return self._client.request("getLead", {"id": id}, OMITTED, headers, timeout)

    def update_lead(
        self,
        *,
        id: "LeadId",
        body: "LeadUpdate",
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "Lead":
        """Set a lead's status and note

        Sets the absolute state, so repeating a request changes nothing (idempotent by construction). An Idempotency-Key additionally replays the first answer without a second audit entry. Audited; same-origin and application/json only.

        PATCH /api/leads/{id}
        """
        return self._client.request("updateLead", {"id": id, "Idempotency-Key": idempotency_key}, body, headers, timeout)


