        """One registry

        stakeholders, metrics, report-types, findings (rules with their evidence metrics resolved), commitments (with status) and legal (documents with their publish blockers, from core legal.js).

        GET /api/registries/{name}
        """
        return self._client.request("getRegistry", {"name": name}, OMITTED, headers, timeout)


