class _suppressions:
    """Operations of suppressions."""

    def __init__(self, client: Client) -> None:
        self._client = client

    def list_suppressions(
        self,
        *,
        reason: Optional["SuppressionReason"] = None,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "SuppressionPage":
        """The suppression list

        comms_suppression: recipient hashes only.

        GET /api/suppressions
        """
        return self._client.request("listSuppressions", {"reason": reason, "limit": limit, "cursor": cursor}, OMITTED, headers, timeout)

    def add_suppression(
        self,
        *,
        body: "SuppressionAdd",
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "SuppressionAdded":
        """Add a suppression

        Goes through the comms engine's POST /v1/comms/suppress, which hashes an address itself. The address, when given, is passed on and never stored by the admin. Recording the same recipient and reason again only refreshes it. Audited.

        POST /api/suppressions
        """
        return self._client.request("addSuppression", {"Idempotency-Key": idempotency_key}, body, headers, timeout)

    def remove_suppression(
        self,
        *,
        recipient_hash: "Sha256Hex",
        reason: "SuppressionReason",
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "SuppressionRemoved":
        """Remove a suppression

        Deletes one (recipient_hash, reason) row. A dsar-erasure suppression is permanent and cannot be removed (409). Removing a row that is not there is a 404. Audited before and after.

        DELETE /api/suppressions/{recipient_hash}/{reason}
        """
        return self._client.request("removeSuppression", {"recipient_hash": recipient_hash, "reason": reason, "Idempotency-Key": idempotency_key}, OMITTED, headers, timeout)


class _users:
    """Operations of users."""

    def __init__(self, client: Client) -> None:
        self._client = client

    def list_roles(
        self,
        *,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "RoleList":
        """Roles and what each may do (RBAC)

        The roles of the admin and the permissions each holds, from the Worker's configuration. Every operation of this contract names the permission it needs (x-permission).

        GET /api/roles
        """
        return self._client.request("listRoles", {}, OMITTED, headers, timeout)

    def list_users(
        self,
        *,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "UserPage":
        """Who can use the admin

        The identities on the Access allowlist (role owner, by hash) and any principal registered in the admin's database (none until an invitation is accepted, which needs the Access policy widened by the lead). Addresses are never shown.

        GET /api/users
        """
        return self._client.request("listUsers", {"limit": limit, "cursor": cursor}, OMITTED, headers, timeout)

    def list_invitations(
        self,
        *,
        state: Optional["InvitationState"] = None,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "InvitationPage":
        """Invitations

        Invitations recorded by the admin: the invitee as a hash, the role, the state. An invitation grants nothing by itself: access is decided by the Cloudflare Access policy and the allowlist secret, which the lead changes.

        GET /api/invitations
        """
        return self._client.request("listInvitations", {"state": state, "limit": limit, "cursor": cursor}, OMITTED, headers, timeout)

    def create_invitation(
        self,
        *,
        body: "InvitationCreate",
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "Invitation":
        """Record an invitation

        Stores the invitee's address as a hash with a role (never the address) and an expiry. No email is sent: the admin has no mail path of its own, and access still needs the Access policy. Audited.

        POST /api/invitations
        """
        return self._client.request("createInvitation", {"Idempotency-Key": idempotency_key}, body, headers, timeout)

    def revoke_invitation(
        self,
        *,
        id: "InvitationId",
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
    ) -> "Invitation":
        """Revoke a pending invitation

        Only a pending invitation can be revoked. Audited.

        POST /api/invitations/{id}/revoke
        """
        return self._client.request("revokeInvitation", {"id": id, "Idempotency-Key": idempotency_key}, OMITTED, headers, timeout)
